-- SEO tekstovi kategorija: Hrvatska kao cjelina umjesto samo Splita i Dubrovnika (gradovi ostaju kao ključne riječi).
-- Iste izmjene su u seed_category_seo_2.sql. Mijenja samo tekstove koji još imaju stari oblik.

update public.categories
set
  description = replace(replace(replace(replace(replace(replace(description, '## Iz Splita, Dubrovnika i cijele Dalmacije', '## Kupci iz cijele Hrvatske'), 'Mnoge kupce iz Dalmacije rado dočekujemo u Mostaru, osobito u sezoni matura i vjenčanja.', 'Kupce iz cijele Hrvatske, od Zagreba do Splita i Dubrovnika, rado dočekujemo u Mostaru, osobito u sezoni matura i vjenčanja.'), 'Butik u Mepas Mallu u Mostaru, blizu Splita i Dubrovnika.', 'Butik u Mepas Mallu u Mostaru, za kupce iz BiH i Hrvatske.'), 'Kupci nam dolaze i iz Splita i Dubrovnika.', 'Kupci nam dolaze iz BiH i cijele Hrvatske.'), '## Maturantice iz Dalmacije', '## Maturantice iz Hrvatske'), 'Maturalne haljine u Mostaru biraju i maturantice iz Splita, Dubrovnika i Makarske.', 'Maturalne haljine u Mostaru biraju i maturantice iz cijele Hrvatske, od Splita i Makarske do Dubrovnika.'),
  meta_description = replace(replace(replace(replace(replace(replace(meta_description, '## Iz Splita, Dubrovnika i cijele Dalmacije', '## Kupci iz cijele Hrvatske'), 'Mnoge kupce iz Dalmacije rado dočekujemo u Mostaru, osobito u sezoni matura i vjenčanja.', 'Kupce iz cijele Hrvatske, od Zagreba do Splita i Dubrovnika, rado dočekujemo u Mostaru, osobito u sezoni matura i vjenčanja.'), 'Butik u Mepas Mallu u Mostaru, blizu Splita i Dubrovnika.', 'Butik u Mepas Mallu u Mostaru, za kupce iz BiH i Hrvatske.'), 'Kupci nam dolaze i iz Splita i Dubrovnika.', 'Kupci nam dolaze iz BiH i cijele Hrvatske.'), '## Maturantice iz Dalmacije', '## Maturantice iz Hrvatske'), 'Maturalne haljine u Mostaru biraju i maturantice iz Splita, Dubrovnika i Makarske.', 'Maturalne haljine u Mostaru biraju i maturantice iz cijele Hrvatske, od Splita i Makarske do Dubrovnika.'),
  seo_text = replace(replace(replace(replace(replace(replace(seo_text, '## Iz Splita, Dubrovnika i cijele Dalmacije', '## Kupci iz cijele Hrvatske'), 'Mnoge kupce iz Dalmacije rado dočekujemo u Mostaru, osobito u sezoni matura i vjenčanja.', 'Kupce iz cijele Hrvatske, od Zagreba do Splita i Dubrovnika, rado dočekujemo u Mostaru, osobito u sezoni matura i vjenčanja.'), 'Butik u Mepas Mallu u Mostaru, blizu Splita i Dubrovnika.', 'Butik u Mepas Mallu u Mostaru, za kupce iz BiH i Hrvatske.'), 'Kupci nam dolaze i iz Splita i Dubrovnika.', 'Kupci nam dolaze iz BiH i cijele Hrvatske.'), '## Maturantice iz Dalmacije', '## Maturantice iz Hrvatske'), 'Maturalne haljine u Mostaru biraju i maturantice iz Splita, Dubrovnika i Makarske.', 'Maturalne haljine u Mostaru biraju i maturantice iz cijele Hrvatske, od Splita i Makarske do Dubrovnika.')
where concat_ws(' ', description, meta_description, seo_text) ~ '(Splita|Dalmacij)';
